// ============================================================
// CONFIG – new member mug numbers (see README.md)
// ============================================================
return [{ json: {
  LOCATION_ID: 'XTpY4DQ6CrYVvesFdX3K',
  MEMBER_TAG: 'mug-club-member', // added to everyone who goes through this workflow
  MUG_DIGITS: 5,        // 3150 -> "03150"
  START_AFTER: 0,       // highest mug number already handed out outside GHL (imported Toast guests are read from GHL)
  SKIP: [],             // mug numbers never to hand out, e.g. [1, 13, 100]
  ASSIGNED_TAG: 'mug-assigned', // GHL workflow on this tag sends the member their mug number by SMS
  FIELD_IDS: {
    mugNumber: 'vWklTcHjmQV1tW52XIAb',
    freePourStatus: 'nQ1XQVxK7dt5x2jkmzQK',
    fourPackStatus: 'CPdRbUyVL44UpTcIOHzc',
    merchStatus: 'hUof3kNaxMaSle2hym89',
    mugPricingStatus: 'wrl8FbQuiPNbEATFZcUY',
  },
  ORDERED_TAG: 'order processing by vendor',   // GHL workflow on this tag sends the member the "your mug is being made" message
  MUG_STATUS_FIELD: 'citZ7RA1sh8YIjMkfmhH', // GHL dropdown: Ordered / Received / Delivered (leave as is to skip status tracking)
  ARCANE: {
    CONTACT_ID: 'REPLACE_WITH_ARCANE_CONTACT_ID', // GHL contact for Arcane Engraving (its email is where orders go); leave as is to skip the email
    SUBJECT: 'Mug order #{mug}',
    // {mug} {name} {date} are filled in. Change this text to match Arcane's order format.
    BODY: 'New mug order\n\nMug number: {mug}\nMember name: {name}\nDate ordered: {date}\n',
  },
  PIPELINE: { id: 'ay4k4DUjXvvQaYnmmjIA', available: '10497e96-254f-471e-8571-66b59f4b1dc5' },
}}];

// One search request per page of contacts with a mug number (every guest and member).
const items = [];
for (let page = 1; page <= 50; page++) items.push({ json: { page, pageLimit: 100 } }); // up to 5,000 contacts
return items;

// Gives the new member the next free mug number (highest in GHL + 1).
// A contact who already has one (member, or imported Toast guest) keeps it.
// A new member also gets the mug ordered: status Ordered, a tag for the member message, and an email to Arcane.
// Perk statuses are only filled where empty, so perks already redeemed stay redeemed.
const cfg = $('Config').first().json;
const contact = $('Get Contact').first().json.contact || {};
const mugOf = (c) => {
  const f = (c.customFields || []).find(x => x.id === cfg.FIELD_IDS.mugNumber);
  return f && f.value ? String(f.value).trim() : '';
};
const name = [contact.firstName, contact.lastName].filter(Boolean).join(' ') || contact.email || contact.id;
const own = mugOf(contact);
const wasMember = (contact.tags || []).includes(cfg.MEMBER_TAG);
const current = {};
for (const f of contact.customFields || []) current[f.id] = f.value;
const available = (id) => (current[id] ? [] : [{ id, field_value: 'Available' }]);
const perkStatuses = () => [
  ...available(cfg.FIELD_IDS.freePourStatus),
  ...available(cfg.FIELD_IDS.fourPackStatus),
  ...available(cfg.FIELD_IDS.merchStatus),
  ...available(cfg.FIELD_IDS.mugPricingStatus),
];
const isSet = (v) => v && !String(v).startsWith('REPLACE');
const statusField = isSet(cfg.MUG_STATUS_FIELD) ? cfg.MUG_STATUS_FIELD : '';
// A mug is ordered for every new member, but not when someone signs up again or already has a mug status
const orderMug = !wasMember && !(statusField && current[statusField]);
const tags = [cfg.ASSIGNED_TAG, cfg.MEMBER_TAG, ...(orderMug ? [cfg.ORDERED_TAG] : [])];
const orderUpdates = () => (orderMug && statusField ? [{ id: statusField, field_value: 'Ordered' }] : []);
if (own) {
  return [{ json: { contactId: contact.id, name, mug: own, alreadyHad: true, wasMember, orderMug, tags, fieldUpdates: [...perkStatuses(), ...orderUpdates()] } }];
}

const taken = new Set();
let max = cfg.START_AFTER;
for (const item of $input.all()) {
  for (const c of item.json.contacts || []) {
    const n = parseInt(mugOf(c).replace(/\D/g, ''), 10);
    if (!n) continue;
    taken.add(n);
    if (n > max) max = n;
  }
}
// GHL search can lag a few seconds behind; never reuse a number this workflow just gave out
const seen = $getWorkflowStaticData('global');
if ((seen.lastMug || 0) > max) max = seen.lastMug;

let n = max + 1;
while (taken.has(n) || cfg.SKIP.includes(n)) n++;
seen.lastMug = n;
if (n >= 10 ** cfg.MUG_DIGITS) throw new Error(`No ${cfg.MUG_DIGITS}-digit mug numbers left – raise MUG_DIGITS`);
const mug = String(n).padStart(cfg.MUG_DIGITS, '0');
return [{ json: { contactId: contact.id, name, mug, alreadyHad: false, wasMember, orderMug, tags,
  fieldUpdates: [{ id: cfg.FIELD_IDS.mugNumber, field_value: mug }, ...perkStatuses(), ...orderUpdates()] } }];

// Mug order email for Arcane Engraving, sent from GHL. The wording lives in Config > ARCANE.
const cfg = $('Config').first().json;
const m = $('Pick Mug Number').first().json;
const a = cfg.ARCANE;
if (!a.CONTACT_ID || a.CONTACT_ID.startsWith('REPLACE')) return []; // email not set up yet: nothing is sent
const fill = (s) => s.replace(/\{mug\}/g, m.mug).replace(/\{name\}/g, m.name).replace(/\{date\}/g, $now.toFormat('yyyy-MM-dd'));
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { contactId: a.CONTACT_ID, subject: fill(a.SUBJECT), html: esc(fill(a.BODY)).replace(/\n/g, '<br>') } }];
